import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button, Input, FormGroup, Label } from 'reactstrap';

const EditProposalModal = ({ isOpen, toggle, proposal, onUpdate }) => {
    const [term, setTerm] = useState('');
    const [payWay, setPayWay] = useState('');
    const [pay, setPay] = useState('');

    useEffect(() => {
        if (proposal) {
            setTerm(proposal.term);
            setPayWay(proposal.payWay);
            setPay(proposal.pay);
        }
    }, [proposal]);

    const handleUpdate = () => {
        const updatedProposal = {
            ...proposal,
            term,
            payWay,
            pay,
        };
        onUpdate(updatedProposal);
        toggle();
    };

    return (
        <Modal isOpen={isOpen} toggle={toggle}>
            <ModalHeader toggle={toggle}>제안서 수정</ModalHeader>
            <ModalBody>
                <FormGroup>
                    <Label for="term">업로드 기간</Label>
                    <Input type="text" id="term" value={term} onChange={(e) => setTerm(e.target.value)} />
                </FormGroup>
                <FormGroup>
                    <Label for="payWay">지급 방법</Label>
                    <Input
                        type="select"
                        name="payWay"
                        id="payWay"
                        value={payWay}
                        onChange={(e) => setPayWay(e.target.value)}
                    >
                        <option value="">선택하세요</option>
                        <option value="분할 지급">분할 지급</option>
                        <option value="선불">선불</option>
                        <option value="후불">후불</option>
                    </Input>
                </FormGroup>
                <FormGroup>
                    <Label for="pay">총 금액</Label>
                    <Input type="number" id="pay" value={pay} onChange={(e) => setPay(parseFloat(e.target.value))} />
                </FormGroup>
            </ModalBody>
            <ModalFooter>
                <Button color="primary" onClick={handleUpdate}>
                    수정
                </Button>
                <Button color="secondary" onClick={toggle}>
                    취소
                </Button>
            </ModalFooter>
        </Modal>
    );
};

export default EditProposalModal;
